package com.uniquebrave.app;
import android.app.Activity; import android.os.Bundle; import android.webkit.WebView; import android.webkit.WebViewClient;
public class MainActivity extends Activity { private WebView web; @Override public void onCreate(Bundle b){super.onCreate(b); web=new WebView(this); web.setWebViewClient(new WebViewClient()); web.getSettings().setJavaScriptEnabled(true); web.getSettings().setDomStorageEnabled(true); web.loadUrl("https://brave-hub.onrender.com/"); setContentView(web);} @Override public void onBackPressed(){if(web.canGoBack())web.goBack();else super.onBackPressed();}}